def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    out = []
    seen = set()
    for r in rows:
        try:
            key = r if hash(r) is not None else None
        except TypeError:
            key = None
        if key is None:
            # Unhashable row: fall back to a linear membership check.
            if r in out:
                continue
        elif key in seen:
            continue
        else:
            seen.add(key)
        out.append(r)
    return out

